{"attribute": "code example", "value": "<!DOCTYPE html>
<html>
  <head>
    <meta charset="UTF-8">
    <title>Ball Following Mouse</title>
    <style>
      #ball {
        width: 50px;
        height: 50px;
        border-radius: 50%;
        background-color: red;
        position: absolute;
      }
    </style>
  </head>
  <body>
    <div id="ball"></div>
    <script>
      var ball = document.getElementById("ball");
      document.addEventListener("mousemove", function(event) {
        var x = event.clientX;
        var y = event.clientY;
        ball.style.left = (x - 25) + "px";
        ball.style.top = (y - 25) + "px";
      });
    </script>
  </body>
</html>", "context": "Write me a code to add to a Google website I made that will make a ball follow the mouse pointer"}
